sys_script_include.script:
var getCotrastAPI = Class.create();
getCotrastAPI.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getDetails: function() {
        var obj = {};

        var configGR = new GlideRecordSecure("sn_sec_int_impl_config");
        configGR.addEncodedQuery("sys_scope.name=Contrast Security Application Vulnerability Integration");

        configGR.query();
        while (configGR.next()) {
            obj[configGR.configuration.getDisplayValue()] = configGR.value.toString();
        }
        return JSON.stringify(obj);
    },

    type: 'getCotrastAPI'
});
